  const reqBody=JSON.stringify({systemInstruction:{parts:[{text:system}]},contents:[{role:'user',parts:[{text:prompt}]}],generationConfig:{responseMimeType:'application/json',responseJsonSchema:planSchema(),maxOutputTokens:65536,thinkingConfig:{thinkingLevel:'high',includeThoughts:true}}});
